class Solution:
    def maximumSubsequenceCount(self, text: str, pattern: str) -> int:
        def count(s):
            res = seen = 0
            for ch in s:
                if ch == pattern[1]:
                    res += seen
                if ch == pattern[0]:
                    seen += 1
            return res

        best = 0
        for ch in pattern:
            for i in range(len(text) + 1):
                best = max(best, count(text[:i] + ch + text[i:]))
        return best

